def solve(start, end, bookings):
    if start >= end:
        return []
    occupied = []
    for a, b in bookings:
        if a < b and b > start and a < end:
            occupied = occupied + [[max(a, start), min(b, end)]]
    occupied = sorted(occupied)
    free = []
    cursor = start
    for a, b in occupied:
        if a > cursor:
            free = free + [[cursor, a]]
        if b > cursor:
            cursor = b
    if cursor < end:
        free = free + [[cursor, end]]
    return free

